using Essco.Application.Auditing;using Essco.Application.Configuration;using Essco.Application.Returns;using Essco.Application.Security;using Essco.Domain.Returns;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.Extensions.Options;
namespace Essco.Web.Pages.Returns;[Authorize(Policy=Permissions.Billing)]public sealed class IndexModel(ReturnService service,AuditService audit,IOptions<EsscoOptions> options):PageModel
{[BindProperty(SupportsGet=true)]public FilterModel Filter{get;set;}=new();public IReadOnlyCollection<ReturnRequest>Items{get;private set;}=[];public ReturnRequest?Selected{get;private set;}[TempData]public string?StatusMessage{get;set;}public async Task OnGetAsync(int? view,CancellationToken t){Items=await service.ListAsync(Filter.Domain(),t);if(view is not null)Selected=await service.GetAsync(view.Value,t);}public async Task<IActionResult>OnPostProcessAsync(int number,CancellationToken t){var r=await service.DispatchAsync(number,options.Value.DefaultCompany,User.Identity?.Name??"",t);await audit.WriteAsync(null,User.Identity?.Name??"",options.Value.DefaultCompany,"return.process","Devoluciones",number.ToString(),r.Succeeded?"Queued":"Rejected",HttpContext.TraceIdentifier,HttpContext.Connection.RemoteIpAddress?.ToString(),t);StatusMessage=r.Succeeded?$"Devolución encolada. Trabajo: {r.Job!.Id}":r.Error;return RedirectToPage();}public sealed class FilterModel{public string?Driver{get;set;}public int?Number{get;set;}public string Status{get;set;}="Pending";public ReturnFilter Domain()=>new(Status=="All"?null:Status=="Processed",Driver,Number);}}
